import{_ as i,C as s,o as n,c as r,a6 as o,E as t}from"./chunks/framework.CKIbuWFA.js";const v=JSON.parse('{"title":"Instalar y administrar plugins","description":"","frontmatter":{"title":"Instalar y administrar plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","translationRevision":"7e9ad6d138cf11ac73bc3755527638092c10edd155712b3e99e6fcbc47cf0626","order":10},"headers":[],"relativePath":"es/user/plugins/index.md","filePath":"es/user/plugins/index.md","lastUpdated":1794611623000}'),l={name:"es/user/plugins/index.md"};function c(d,e,u,p,m,f){const a=s("DemoFrame");return n(),r("div",null,[e[0]||(e[0]=o('<h1 id="install-and-manage-plugins" tabindex="-1">Instalar y administrar plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to &quot;Instalar y administrar plugins {#install-and-manage-plugins}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Añade una integración, revisa el acceso solicitado y confirma que sus acciones funcionan. Necesitas un paquete de escritorio compatible con el sistema operativo, arquitectura y versión del host exigidos por el plugin. El catálogo remoto y las descargas requieren Internet; algunos servicios también necesitan <a href="./../cloud/account.html">sesión de Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Revisar antes de activar <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to &quot;Revisar antes de activar {#review-before-enabling}&quot;">​</a></h2><ol><li>Abre <strong>Plugins</strong> y consulta Installed, Explore o Updates. Explore solicita únicamente plugins. Las plantillas y perfiles se encuentran en <a href="./../automations/templates.html">Automations</a>.</li><li>Selecciona un plugin para revisar descripción, versión, compatibilidad y entorno de ejecución. Comprueba editor, capacidades y permisos; el nombre visible por sí solo no demuestra confianza.</li><li>Usa el flujo de instalación para inspeccionar la vista previa del paquete. Revisa versión exacta, información de firma, acceso solicitado y diferencias respecto a la versión instalada antes de confirmar.</li><li>Espera el resultado del trabajo de instalación. Descargar, instalar y activar son etapas distintas; una tarjeta del catálogo no significa que el plugin esté preparado.</li><li>Abre sus paneles Settings o Connection. Introduce dirección y credenciales únicamente en los campos previstos. Usa la comprobación de conexión declarada si existe.</li><li>Activa el plugin y comprueba si aparecen sus acciones o páginas. Crea una <a href="./../automations/first-rule.html">regla de registro</a> limitada antes de vincular una acción externa potente.</li></ol><p>Los plugins pueden ejecutar código nativo o procesos separados. Un proceso puede aislar un fallo, pero no constituye una zona aislada del sistema operativo. Instala software de editores confiables. Una firma válida identifica la procedencia del paquete revisado; no garantiza que todos sus efectos sean apropiados para tu flujo.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles la revisión de paquetes, los trabajos de instalación, las preferencias y la gestión de versiones. Las acciones concretas dependen del manifiesto instalado, las capacidades del host y el servicio externo. Los procesadores de eventos tienen un panel propio y pueden añadir campos de análisis opcionales; los campos originales siguen siendo distintos.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Ante un fallo, lee el error del trabajo para identificar incompatibilidad, firma, entorno o descarga. Evita debilitar la verificación para eliminar un aviso. Si una actualización falla, revisa las versiones conservadas y usa la reversión cuando esté disponible. Comprueba automatizaciones dependientes antes de desactivar o desinstalar. Conserva <a href="./../preferences/backups.html">copias</a> de datos y configuración antes de eliminarlos.</p>',10)),t(a,{scenario:"plugins",locale:"es",tour:"plugin",title:"Demo de plugins"})])}const b=i(l,[["render",c]]);export{v as __pageData,b as default};
